package com.lend.model;

public class Loan {

    private String loanId;
    private double upb;

    public String getLoanId() {
        return loanId;
    }

    public void setLoanId(String loanId) {
        this.loanId = loanId;
    }

    public double getUpb() {
        return upb;
    }

    public void setUpb(double upb) {
        this.upb = upb;
    }
}
